+func loadUIAsset(sub fs.FS, name string) *uiAsset {
+	v, _ := uiAssets.LoadOrStore(name, &uiAsset{})
+	a := v.(*uiAsset)
+	a.once.Do(func() {
+		a.raw, a.err = fs.ReadFile(sub, name)
+		if a.err != nil {
+			return
+		}
+		sum := sha256.Sum256(a.raw)
+		tag := hex.EncodeToString(sum[:8])
