+		w.WriteHeader(http.StatusNotModified)
+		return
+	}
+	if gz {
+		h.Set("Content-Encoding", "gzip")
+		h.Set("Content-Length", strconv.Itoa(len(a.gz)))
+		w.Write(a.gz)
+		return
+	}
+	h.Set("Content-Length", strconv.Itoa(len(a.raw)))
+	w.Write(a.raw)
